/* @lc app=leetcode id=2905 lang=kotlin */ class Solution { fun findIndices(nums: IntArray, indexDifference: Int, valueDifference: Int): IntArray = nums.indices.drop(indexDifference).fold(Triple(0, 0, intArrayOf(-1, -1))) { (mn, mx, ans), j -> (j - indexDifference).let { i -> (if (nums[i] < nums[mn]) i else mn).let { m1 -> (if (nums[i] > nums[mx]) i else mx).let { m2 -> Triple(m1, m2, if (ans[0] != -1) ans else if (Math.abs(nums[j] - nums[m1]) >= valueDifference) intArrayOf(m1, j) else if (Math.abs(nums[j] - nums[m2]) >= valueDifference) intArrayOf(m2, j) else ans) } } } }.third }